"""Writes data.js for the buy menu look test 33: what the slice sells today, copied from World/rules.
Run from anywhere: python Art/StyleTests/buy_menu_33/make_data.py"""
import json, os
here = os.path.dirname(os.path.abspath(__file__))
root = os.path.normpath(os.path.join(here, "..", "..", ".."))
R = lambda n: json.load(open(os.path.join(root, "World", "rules", n), encoding="utf-8"))
goods, eco, furn, des, outs = R("mall_goods.json"), R("economy.json"), R("furnishing.json"), R("designer.json"), R("mall_outlets.json")
data = {
    "note": "Generated by Art/StyleTests/buy_menu_33/make_data.py from World/rules. Do not edit.",
    "per_outlet": goods["per_outlet"], "stock_target": goods["stock"]["target"], "restock_minute": eco["stock"]["restock_minute"],
    "goods": goods["goods"], "sells": goods["sells"],
    "kinds": {k: {"label": v["label"], "name": v["names"][0], "trade": v.get("trade"), "sign": v.get("sign")} for k, v in outs["kinds"].items()},
    "items": {k: v for k, v in eco["items"].items() if not v.get("quest")},
    "shops": {k: {"name": v["name"], "sells": v["sells"]} for k, v in eco["shops"].items() if k != "mall"},
    "rooms": furn["rooms"], "lines": furn["lines"],
    "pieces": {k: {a: v[a] for a in ("name", "size", "price", "from", "rug", "small") if a in v} for k, v in furn["pieces"].items()},
    "palette": des["palette"],
}
with open(os.path.join(here, "data.js"), "w", encoding="utf-8", newline="\n") as f:
    f.write("// " + data["note"] + "\nwindow.BUY_DATA = " + json.dumps(data, separators=(",", ":"), ensure_ascii=False) + ";\n")
print("data.js", os.path.getsize(os.path.join(here, "data.js")), "bytes;", len(data["goods"]), "goods,", len(data["items"]), "items,", len(data["pieces"]), "pieces")
